use std::collections::{BTreeMap, BTreeSet};
use unisphere_sdk::query::*;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let id = EntityId::derive(EntityKind::Session, [b"external-session".as_slice()]);
    let row = ProjectedRow::new(
        Dataset::Sessions, id, Vec::new(),
        BTreeMap::from([(FieldId::Name, FieldValue::Null)]),
        &ContentAccess { inspect_fields: BTreeSet::new(), emit_content: true },
    )?;
    let encoded = serde_json::to_value(&row)?;
    assert_eq!(encoded["fields"].get("name"), Some(&serde_json::Value::Null));
    assert!(encoded["fields"].get("model").is_none());
    let inspected = ContentAccess { inspect_fields: BTreeSet::from([FieldId::Text]), emit_content: false };
    let denied = ProjectedRow::new(
        Dataset::Messages,
        EntityId::derive(EntityKind::Message, [b"external-message".as_slice()]),
        Vec::new(),
        BTreeMap::from([(FieldId::Text, FieldValue::String("PRIVATE-SMOKE-SENTINEL".into()))]),
        &inspected,
    );
    let failure = match denied { Ok(_) => panic!("inspection became output consent"), Err(failure) => failure };
    assert_eq!(failure.kind(), QueryFailureCode::ContentConsentRequired);
    assert!(!serde_json::to_string(&failure)?.contains("PRIVATE-SMOKE-SENTINEL"));
    let query = Digest::of_bytes(b"query");
    let view = Digest::of_bytes(b"view");
    let mismatch = CursorBinding { query_digest: Digest::of_bytes(b"other-query"), view_digest: Digest::of_bytes(b"other-view") }
        .validate(query, view).unwrap_err();
    assert_eq!(mismatch.cursor_reason(), Some(CursorMismatchReason::QueryOptionsChanged));
    let invalid = QueryLimits { max_sources: 0, ..QueryLimits::default() }.validate().unwrap_err();
    assert_eq!(invalid.kind(), QueryFailureCode::ResourceLimit);
    let reported = Timestamp::parse("2026-09-01T00:00:00.000000001Z", TimestampBasis::SourceReported)?;
    let supplied: Timestamp = serde_json::from_str(&serde_json::to_string(&reported)?)?;
    assert_eq!(supplied.unix_nanos(), reported.unix_nanos());
    assert_eq!(supplied.basis(), TimestampBasis::SuppliedUnknown);
    let json_capability = schema(Dataset::Sessions).formats.iter()
        .find(|capability| capability.format == OutputFormat::Json).unwrap();
    assert!(json_capability.lossy);
    assert!(json_capability.losses.contains(&FormatLoss::TimestampBasis));
    let fixtures = unisphere_testkit::query::shared_query_fixture();
    let source = fixtures.into_iter().find(|source| !source.observations.is_empty())
        .expect("shared fixture must supply native observations");
    source.validate(&QueryLimits::default())?;
    let mut wrong_revision = source;
    wrong_revision.source.revision.push_str("-changed");
    assert_eq!(wrong_revision.validate(&QueryLimits::default()).unwrap_err().kind(), QueryFailureCode::InvalidData);
    println!("{}", serde_json::json!({"scope":"external public SDK query contracts", "projected_null":true,"content_consent":true,"typed_cursor_reason":true,"invalid_limits":true,"timestamp_provenance":true,"typed_fixture_revision_rejected":true,"query_service_implemented":false}));
    Ok(())
}
